 const pages=Math.max(1,Math.ceil(rows.length/15));page=Math.max(1,Math.min(page,pages));const fmt=n=>Number(n).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});
 el.innerHTML='<div class="soaTableHeading">☷ Outlet-wise Transaction Details (All Distributors)<span>Total Outlets: '+db.outlets.length+'</span></div><div class="soaTableTools"><input id="soaSearch" type="search" placeholder="Search outlet, distributor..." value="'+esc(query)+'"><span>Page '+page+' of '+pages+'</span><button id="soaPrev" '+(page===1?'disabled':'')+'>‹</button><button id="soaNext" '+(page===pages?'disabled':'')+'>›</button></div><div class="soaTableWrap"><table class="soaPremiumTable"><thead><tr><th>No.</th><th>Distributor ID</th><th>Outlet Name</th><th>Debit (RM)</th><th>Credit (RM)</th><th>Balance (RM)</th></tr></thead><tbody>'+rows.slice((page-1)*15,page*15).map((x,i)=>'<tr><td>'+((page-1)*15+i+1)+'</td><td>'+esc(x.o.id)+'</td><td>'+esc(x.o.name)+'</td><td>'+fmt(x.debit)+'</td><td>'+fmt(x.credit)+'</td><td>'+fmt(x.balance)+'</td></tr>').join('')+'</tbody></table></div>';
 byId('soaSearch').oninput=e=>{query=e.target.value;page=1;refresh();};byId('soaPrev').onclick=()=>{page--;refresh()};byId('soaNext').onclick=()=>{page++;refresh()};return;
