let opening=false,soaHistory=false;
async function open(){if(visible||opening)return;opening=true;try{await loadPermissions();await loadCloud();visible=true;remember();const root=document.createElement('div');root.id='ffhSoaRoot';document.body.appendChild(root);positionSoa();requestAnimationFrame(positionSoa);history.pushState({...history.state,ffhSoaOverlay:true},'',location.href);soaHistory=true;render();}catch(e){alert(e.message);}finally{opening=false;}}
let lastSoaTop=0,lastSoaBottom=0;
function positionSoa(){
 const root=byId('ffhSoaRoot');if(!root)return;
 const app=document.querySelector('#app .app')||document.querySelector('.app')||document.getElementById('app');
 const top=app?.querySelector('header.top')||document.querySelector('header.top');
 const ann=app?.querySelector('.ffAppAnnouncements')||document.querySelector('.ffAppAnnouncements');
 const bottom=app?.querySelector('nav.bottom')||document.querySelector('nav.bottom');
 const visibleRect=el=>{if(!el)return null;const r=el.getBoundingClientRect();return r.width>0&&r.height>0?r:null;};
 const topRect=visibleRect(top),annRect=visibleRect(ann),bottomRect=visibleRect(bottom);
 const measuredTop=Math.max(topRect?.bottom||0,annRect?.bottom||0);
 if(measuredTop>40&&measuredTop<window.innerHeight*.6)lastSoaTop=Math.round(measuredTop);
 if(bottomRect&&bottomRect.top>window.innerHeight*.4)lastSoaBottom=Math.max(0,Math.round(window.innerHeight-bottomRect.top));
 root.style.setProperty('top',(lastSoaTop||0)+'px','important');
 root.style.setProperty('bottom',lastSoaBottom+'px','important');
 root.style.setProperty('--soa-actions-bottom',lastSoaBottom+'px');
}
window.addEventListener('resize',()=>{if(visible)positionSoa();});
function close(fromHistory=false){if(soaExitPrompt){soaExitPrompt.remove();soaExitPrompt=null;}dismissSoaModal();if(!visible)return;visible=false;remember();byId('ffhSoaRoot')?.remove();if(!fromHistory&&soaHistory&&history.state?.ffhSoaOverlay){soaHistory=false;history.back();}else soaHistory=false;}
let soaExitPrompt=null;
function showSoaExitPrompt(){
 if(soaExitPrompt)return;
 const overlay=document.createElement('div');overlay.className='soaExitOverlay';
 overlay.innerHTML='<section class="soaExitDialog" role="dialog" aria-modal="true" aria-labelledby="soaExitTitle"><div class="soaExitSymbol">!</div><h2 id="soaExitTitle">EXIT SOA?</h2><p>Are you sure you want to exit SOA and return to Home?</p><div class="soaExitButtons"><button type="button" id="soaExitCancel">CANCEL</button><button type="button" id="soaExitYes">YES, EXIT</button></div></section>';
 document.body.appendChild(overlay);soaExitPrompt=overlay;
 overlay.querySelector('#soaExitCancel').onclick=()=>{overlay.remove();soaExitPrompt=null;};
 overlay.querySelector('#soaExitYes').onclick=()=>{overlay.remove();soaExitPrompt=null;close(true);const home=document.querySelector('nav.bottom [data-page="home"]');if(home)home.click();};
}
window.addEventListener('popstate',()=>{
 if(!visible)return;
 history.pushState({...history.state,ffhSoaOverlay:true},'',location.href);
 if(soaModalOpen())return;
 showSoaExitPrompt();
});
function install(){
 // Home tiles are rendered by app.js from the modules list; target the stable page key.
 for(const tile of document.querySelectorAll('[data-page="access"]')){
  if(tile.closest('#ffhSoaRoot')||tile.closest('#ffhSoaManagerAccess'))continue;
  tile.dataset.page='soa';
  tile.id='ffhSoaLaunch';
  const label=tile.querySelector('.moduleTitle')||[...tile.querySelectorAll('*')].find(el=>!el.children.length&&/access requests/i.test(el.textContent||''));
  if(label)label.textContent='SOA';
  const icon=tile.querySelector('.mi');
  if(icon){icon.textContent='▤';icon.style.color='#ff6900';}
  if(!tile.dataset.ffhSoaBound){
   tile.dataset.ffhSoaBound='1';
   tile.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();open();},true);
  }
 }
 // The existing "Staff, Zones, Access & Trash" Manager Control option is the staff access entry.
 // Do not inject duplicate rows or copy event handlers.
 document.querySelectorAll('#ffhSoaManagerAccess').forEach(el=>el.remove());
}
